INSERT INTO `{prefix}_forum` VALUES
(1, 0, 80, 0, 'SLAED', 'С чего начать после установки', NOW() - INTERVAL 72 HOUR, 'Сайт установлен, разделы и рубрики созданы. Вот порядок, в котором удобно знакомиться с системой:\n\n1. Войдите в панель администратора по адресу, который установщик показал на последнем шаге.\n2. В «Конфигурациях» задайте название сайта, язык и часовой пояс.\n3. В «Конструкторе сайта» замените логотип, меню и контакты в подвале.\n4. Добавьте первую новость: «Типы материалов» → «Новости» → «Добавить».\n\nТемы и сообщения этого форума — пример наполнения, их можно изменить или удалить.', '', 1, 0, 0, 0, '127.0.0.1', 0, 'Support', 4, NOW() - INTERVAL 70 HOUR, 0, '', NULL, 3),
(2, 0, 85, 0, 'SLAED', 'Как сменить логотип, меню и подвал', NOW() - INTERVAL 48 HOUR, 'Внешний вид сайта настраивается без правки файлов — в разделе панели «Конструктор сайта».\n\n- **Шапка**: логотип, девиз и плашка справа.\n- **Меню**: пункты главного и нижнего меню, их порядок и значки.\n- **Подвал**: адрес, телефон, почта и ссылки на социальные сети.\n- **Страницы**: какие секции и блоки показывает главная и остальные страницы.\n\nИзменения сначала сохраняются как черновик, а на сайте появляются после публикации.', '', 1, 0, 0, 0, '127.0.0.1', 0, 'Support', 5, NOW() - INTERVAL 46 HOUR, 0, '', NULL, 3),
(3, 0, 95, 0, 'SLAED', 'Предлагайте идеи для развития сайта', NOW() - INTERVAL 24 HOUR, 'В этом форуме посетители оставляют идеи и предложения. Ссылка на него стоит на вкладке «Идеи и предложения» у левого края страницы.\n\nСоздавать темы и отвечать могут зарегистрированные пользователи. Права каждого форума задаются в панели администратора, в разделе «Категории».', '', 0, 0, 0, 0, '127.0.0.1', 0, 'SLAED', 0, NOW() - INTERVAL 24 HOUR, 0, '', NULL, 3),
(4, 1, 80, 0, 'Support', 'С чего начать после установки', NOW() - INTERVAL 70 HOUR, 'Добавлю: у каждого раздела панели есть вкладка «Справка». В ней описаны все настройки раздела, поэтому с неё удобно начинать знакомство с незнакомым экраном.', '', 0, 0, 0, 0, '127.0.0.1', 0, 'Support', 0, NOW() - INTERVAL 70 HOUR, 0, '', NULL, 3),
(5, 2, 85, 0, 'Support', 'Как сменить логотип, меню и подвал', NOW() - INTERVAL 46 HOUR, 'Светлая и тёмная схема переключаются значками в правом верхнем углу сайта — посетитель выбирает её сам, и выбор запоминается.', '', 0, 0, 0, 0, '127.0.0.1', 0, 'Support', 0, NOW() - INTERVAL 46 HOUR, 0, '', NULL, 3);
